head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00013";
scwin.disclsAcptTpCd = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00013.onpageload' });
    }
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"docCnt":"0","realAttachCnt":"0"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — disclsAcptTpCd
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.usrTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrTpCd", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_disclsAcptTpCd", fn: function () { return String(String((dma_pageContext.get("disclsAcptTpCd2") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrTpCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00013' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(attachfiledown vs submit) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_15_onclick
 * @description img_15 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_15_onclick = function(e){
    try {
        fn_ViewManualKeyWord(0200000020)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00013.img_15_onclick' }); }
};

/**
 * @method
 * @name grd_resultVo_oncellclick
 * @description grd_resultVo 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultVo_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultVo');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultVo */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["wrtrptMaindocTpCd"] === '1') { await scwin.disclosurePreview(r["docNo"], r["disclsMaindocFormCd"], r["disclsMaindocFormVer"]); return; }
        if (r["wrtrptMaindocTpCd"] !== '1') { await scwin.disclosurePreview(r["docNo"], r["disclsMaindocFormCd"], r["disclsMaindocFormVer"]); return; }
        if (r["wrtrptMaindocTpCd"] !== '1') { await scwin.attachPreview(r["docNo"], r["attachSeq"]); return; }
        await scwin.disclosurePreview(r["docNo"], r["disclsMaindocFormCd"], r["disclsMaindocFormVer"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultVo.oncellclick' });
    }
};

/**
 * @method
 * @name img_163_onclick
 * @description 「제출」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_163_onclick = async function(e){
    try {
        await scwin.submit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00013.img_163_onclick' }); }
};

/**
 * @method
 * @name img_164_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_164_onclick = function(e){
    try {
        scwin.goList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00013.img_164_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_disclosurePreview
 * @description disclosure Preview 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_disclosurePreview = async function () {
    const sbmOptions = {
        id: "tx_fn_disclosurePreview",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosurePreview",
        ref: "dma_disclosurePreviewReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_submit
 * @description submit 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_submit = async function (action) {
    const sbmOptions = {
        id: "tx_fn_submit",
        method: "post",
        action: action ?? "/submission/submit.do?method=submitDocument&reqObjDocAcpNo=",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_attachPreview
 * @description attach Preview 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_attachPreview = async function (action) {
    try { return await $c.data.downFile(action ?? "/submission/attachFileDown.do?method=searchAttachFile", "", ($c.util.getComponent("dma_attachPreviewReq") ? $c.util.getComponent("dma_attachPreviewReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {void}
 * @hidden N
 */
scwin.goList = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil00500/jldfil00500.xml');
};

/**
 * @method
 * @name disclosurePreview
 * @description disclosure Preview 처리
 * @param {*} docNo docNo
 * @param {String} disclsMaindocFormCd disclsMaindocFormCd
 * @param {*} disclsMaindocFormVer disclsMaindocFormVer
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.disclosurePreview = async function (docNo, disclsMaindocFormCd, disclsMaindocFormVer) {
    $c.util.getComponent('dma_disclosurePreviewReq').set('docNo', docNo);
    $c.util.getComponent('dma_disclosurePreviewReq').set('disclsMaindocFormCd', disclsMaindocFormCd);
    $c.util.getComponent('dma_disclosurePreviewReq').set('disclsMaindocFormVer', disclsMaindocFormVer);
    (document.previewFrm || { elements: [] }).target = 'previewWin';
    (document.previewFrm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosurePreview';
    (Promise.resolve($c.win.openPopup("/progress_blank_pop/progress_blank_pop.xml", { id: "previewWin", scrollbars: true, resizable: true, width: "835", height: "550", type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("previewWin"); this.closed = true; } });
    await scwin.tx_fn_disclosurePreview();
};

/**
 * @method
 * @name attachPreview
 * @description attach Preview 처리
 * @param {*} docNo docNo
 * @param {*} attachSeq attachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.attachPreview = async function (docNo, attachSeq) {
    $c.util.getComponent('dma_disclosurePreviewReq').set('docNo', docNo);
    $c.util.getComponent('dma_disclosurePreviewReq').set('attachSeq', attachSeq);
    await scwin.tx_fn_attachPreview('/submission/attachFileDown.do?method=searchAttachFile');
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function () {
    const currentTime = 'null';
    const d = new Date();
    const curDate = d.getMonth() + 1;
    if ((String(($c.session.getUserInfo("usrTpCd")) == null ? '' : ($c.session.getUserInfo("usrTpCd"))).indexOf('$' + '{') >= 0 ? '' : String(($c.session.getUserInfo("usrTpCd")) == null ? '' : ($c.session.getUserInfo("usrTpCd")))) === '4' && '99708' === (dma_disclosurePreviewReq.get("formCd") ?? (() => { throw new Error("unresolved:" + "dma_disclosurePreviewReq.formCd"); })()) && curDate !== '4') {
        if (!await $c.win.confirm("불성실공시여부를 확인하여 조치하시기 바랍니다.")) {
            return;
        }
    }
    if ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.disclsAcptTpCd ?? ""))(dma_pageContext.get("disclsAcptTpCd"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.disclsAcptTpCd ?? ""))(dma_pageContext.get("disclsAcptTpCd")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.disclsAcptTpCd ?? ""))(dma_pageContext.get("disclsAcptTpCd"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.disclsAcptTpCd ?? ""))(dma_pageContext.get("disclsAcptTpCd"))))) === 'F' && "0" === '0') {
        const msg = "본 공시는 첨부문서 없이 작성되었습니다. 공시와 같이 제출해야 할 \n첨부문서가 없는 지 확인하신 후 제출하시기 바랍니다.";
        if (!await $c.win.confirm(msg)) {
            return;
        }
    }
    scwin.progress_bar(true);
    await scwin.tx_fn_submit('/submission/submit.do?method=submitDocument&reqObjDocAcpNo=' + $c.util.getComponent('dma_disclosurePreviewReq').get('reqObjDocAcpNo'));
};

/**
 * @method
 * @name progress_bar
 * @description progress bar 처리
 * @param {*} display display
 * @returns {void}
 * @hidden N
 */
scwin.progress_bar = function (display) {
    const on = (display === undefined || display === 'block' || display === true);
    const cu = $c.util.getComponent('progress_bar_curtain');
    const pb = $c.util.getComponent('prg_processing');
    if (on) {
        if (cu && cu.show) {
            cu.setStyle("display", "");
        }
        if (pb && pb.show) {
            pb.setStyle("display", "");
        }
    } else {
        if (cu && cu.hide) {
            cu.setStyle("display", "none");
        }
        if (pb && pb.hide) {
            pb.setStyle("display", "none");
        }
    }
};
